  \"scripts\": {\n    \"typecheck\": \"tsc --noEmit\",\n    \"build:media\": \"node scripts/build-video-template.mjs\",\n    \"build:host\": \"tsdown --config tsdown.host.config.ts\",\n    \"build:client\": \"tsdown\",\n    \"build\": \"npm run build:media && npm run build:host && npm run build:client && npm run build:licenses\",\n    \"test\": \"node scripts/run-checks.mjs\",\n    \"test:p0\": \"node scripts/p0-smoke.mjs\",\n    \"test:ui\": \"node scripts/ui-smoke.mjs && node scripts/artifact-ui-smoke.mjs && node scripts/studio-flow-smoke.mjs && node scripts/artifact-evidence-smoke.mjs\",\n    \"test:host\": \"node scripts/host-smoke.mjs\",\n    \"test:host:preferences\": \"node scripts/host-preference-smoke.mjs\",\n    \"test:exports\": \"node scripts/office-preview-zoom-smoke.mjs && node scripts/export-smoke.mjs && node scripts/office-preview-client-smoke.mjs && node scripts/office-preview-scaling-smoke.mjs && node scripts/office-metrics-layout-smoke.mjs && node scripts/office-fixed-page-smoke.mjs && node scripts/office-adaptive-smoke.mjs\",\n    \"audit\": \"node scripts/audit-public.mjs\",\n    \"check\": \"npm run typecheck && npm run build && npm test && npm run test:p0 && npm run audit && npm run pack:release\",\n    \"pack:release\": \"node scripts/pack-release.mjs\",\n    \"dev:web\": \"node scripts/dev-web.mjs\",\n    \"build:licenses\": \"node scripts/generate-licenses.mjs\",\n    \"test:asr\": \"node scripts/asr-smoke.mjs\",\n    \"test:host:ui\": \"node scripts/host-ui-smoke.mjs\",\n    \"test:host:mindmap\": \"node scripts/mindmap-host-ui-smoke.mjs\",\n    \"test:host:office\": \"node scripts/office-host-ui-smoke.mjs\"\n  },\n  \"optionalDependencies\": {\n    \"@ladybugdb/core-darwin-arm64\": \"0.20.1\",\n    \"@ladybugdb/core-darwin-x64\": \"0.20.1\",\n    \"@ladybugdb/core-linux-arm64\": \"0.20.1\",\n    \"@ladybugdb/core-linux-x64\": \"0.20.1\",\n    \"@ladybugdb/core-win32-x64\": \"0.20.1\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/co